"""Source-reviewed associative containers and trees.

The descriptions distinguish the implemented contracts from the conventional
meaning of a container name. Source paths are relative to src/.
"""


def section(title, *paragraphs, table=None, bullets=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if table is not None:
        result["table"] = table
    if bullets is not None:
        result["bullets"] = bullets
    return result


def table(columns, rows):
    return {"columns": columns, "rows": rows}


def datatype(name, header, summary, *sections):
    return {"name": name, "header": header, "summary": summary,
            "sections": list(sections)}


